create table trust_evidence_blueprints(id uuid not null,tenant_id uuid not null,rules_version text not null check(rules_version='trust-evidence-blueprint.v1'),brand_truth_card_id uuid not null,brand_truth_version integer not null,action_plan_id uuid not null,input_sha256 char(64) not null,status text not null check(status='draft'),fact_level text not null check(fact_level='F4'),evidence_item_count integer not null check(evidence_item_count>0),evidence_items jsonb not null check(jsonb_typeof(evidence_items)='array'),page_sections jsonb not null check(jsonb_typeof(page_sections)='array'),machine_readable_draft jsonb not null check(jsonb_typeof(machine_readable_draft)='object'),prohibited_claims jsonb not null check(jsonb_typeof(prohibited_claims)='array'),next_evidence_tasks jsonb not null check(jsonb_typeof(next_evidence_tasks)='array'),publication_authorized boolean not null check(publication_authorized=false),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256),foreign key(tenant_id,action_plan_id) references optimization_action_plan_snapshots(tenant_id,id));
create trigger trust_evidence_blueprints_append_only before update or delete on trust_evidence_blueprints for each row execute function reject_immutable_mutation();create trigger trust_evidence_blueprints_no_truncate before truncate on trust_evidence_blueprints for each statement execute function reject_immutable_mutation();alter table trust_evidence_blueprints enable row level security;alter table trust_evidence_blueprints force row level security;create policy trust_evidence_blueprints_tenant_isolation on trust_evidence_blueprints using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
